def analyze(k):
    g=G[k]; h=len(g); w=len(g[0])
    cnt=Counter(x for row in g for x in row); frame=cnt.most_common(1)[0][0]
    Hr=[r for r in range(h) if sum(x==frame for x in g[r])>=0.9*w]
    Vl=[c for c in range(w) if sum(g[r][c]==frame for r in range(h))>=0.9*h]
    # anomaly cols: V-lines ever holding non-frame color
    Ac=set()
    for c in Vl:
        for r in range(h):
            if g[r][c]!=frame: Ac.add(c)
    As=[r for r in Hr if any(g[r][c]!=frame for c in Vl)]
    return frame,Hr,Vl,Ac,As
